def agent_action(sandbox, agent_body, step_count):
    if not hasattr(sandbox, "get_fluid_particles") or not hasattr(sandbox, "apply_force_to_particle"):
        return

    budget = sandbox.FORCE_BUDGET_PER_STEP
    particles = sandbox.get_fluid_particles()
    if not particles:
        return

    def get_prio(p):
        px = p.position.x
        if 18.0 <= px <= 22.0:
            return 0  # Target zone
        elif 14.0 <= px < 18.0:
            return 1  # Post-gravity well
        elif 10.0 <= px < 14.0:
            return 2  # Gravity well
        else:
            return 3  # Early stage
    particles.sort(key=get_prio)

    used = 0.0
    m = 15.0  # Reduced mass multiplier for fine control
    g = 10.0

    for p in particles:
        if used >= budget:
            break
        x, y = p.position.x, p.position.y
        vx, vy = p.linearVelocity.x, p.linearVelocity.y
        fx, fy = 0.0, 0.0

        # --- Target Zone (x=18–22 m) ---
        if 18.0 <= x <= 22.0:
            if y < 2.5:
                fy = m * 8.0
            elif y > 4.0:
                fy = -m * 6.0
            else:
                fy = -m * 3.0 * (y - 3.5)
            if vx < 2.0:
                fx = m * 4.0 * (2.0 - vx)
            if y > 3.0:
                fx += m * 80.0  # Headwind compensation

        # --- Post-Gravity Well (x=14–18 m) ---
        elif 14.0 <= x < 18.0:
            target_y = 4.0
            if y < target_y:
                fy = m * 10.0 * (target_y - y)
            elif y > target_y + 0.5:
                fy = -m * 5.0 * (y - target_y)
            else:
                fy = -m * 2.0 * (y - target_y)
            if vx < 3.0:
                fx = m * 5.0 * (3.0 - vx)
            if y > 3.0:
                fx += m * 70.0

        # --- Gravity Well (x=10–14 m) ---
        elif 10.0 <= x < 14.0:
            target_y = 4.0
            if y < target_y:
                fy = m * 12.0 * (target_y - y)
            elif y > target_y + 0.5:
                fy = -m * 6.0 * (y - target_y)
            else:
                fy = -m * 3.0 * (y - target_y)
            if vx < 4.0:
                fx = m * 6.0 * (4.0 - vx)
            if y > 3.0:
                fx += m * 90.0

        # --- Early Stage (x < 10) ---
        else:
            target_vx = 3.0
            desired_y = 1.5 + 0.625 * (x - 6.0) if x >= 6.0 else 1.5
            fy = m * (g + 5.0 * (desired_y - y))
            fx = m * 4.0 * (target_vx - vx)

        mag = math.sqrt(fx * fx + fy * fy)
        if mag > 0:
            if used + mag <= budget:
                sandbox.apply_force_to_particle(p, fx, fy)
                used += mag
            else:
                scale = (budget - used) / mag
                if scale > 0.1:
                    sandbox.apply_force_to_particle(p, fx * scale, fy * scale)
                    used = budget
